create or replace function public.refresh_restaurant_ai_intelligence() returns jsonb language plpgsql security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;return private.generate_restaurant_ai_intelligence(rid,'refresh');end$$;

create or replace function public.run_ai_intelligence_cycle(p_mode text default 'daily',p_limit integer default 100) returns jsonb language plpgsql security definer set search_path='' as $$declare r record;n int:=0;failed int:=0;errs jsonb:='[]';m text:=case when p_mode in('daily','weekly','monthly') then p_mode else 'daily' end;begin if current_user not in('postgres','service_role') and coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;for r in select id from public.restaurants where status in('approved','active') order by id limit least(greatest(coalesce(p_limit,100),1),500) loop begin perform private.generate_restaurant_ai_intelligence(r.id,m);n:=n+1;exception when others then failed:=failed+1;errs:=errs||jsonb_build_array(jsonb_build_object('restaurant_id',r.id,'error',sqlerrm));end;end loop;return jsonb_build_object('mode',m,'processed',n,'failed',failed,'errors',errs,'generated_at',now());end$$;

create or replace function public.get_restaurant_ai_dashboard() returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;return jsonb_build_object('last_run',(select to_jsonb(x) from(select id,run_type,provider,model,methodology_version,status,error,started_at,completed_at,trace from public.restaurant_ai_runs where restaurant_id=rid order by created_at desc limit 1)x),'latest_report',(select to_jsonb(x) from(select id,report_type,restaurant_health_score,growth_score,customer_health_score,marketing_score,operations_score,summary,sections,generated_at from public.restaurant_ai_reports where restaurant_id=rid order by generated_at desc limit 1)x),'weekly_revenue_forecast',(select to_jsonb(x) from(select predicted_value,lower_bound,upper_bound,confidence,period_start,period_end,explanation from public.restaurant_ai_forecasts where restaurant_id=rid and metric='revenue_pence' and horizon='weekly' order by generated_at desc limit 1)x),'monthly_revenue_forecast',(select to_jsonb(x) from(select predicted_value,lower_bound,upper_bound,confidence,period_start,period_end,explanation from public.restaurant_ai_forecasts where restaurant_id=rid and metric='revenue_pence' and horizon='monthly' order by generated_at desc limit 1)x),'customers',jsonb_build_object('scored',(select count(*) from public.restaurant_ai_customer_scores where restaurant_id=rid),'likely_to_return',(select count(*) from public.restaurant_ai_customer_scores where restaurant_id=rid and return_probability>=70),'high_churn_risk',(select count(*) from public.restaurant_ai_customer_scores where restaurant_id=rid and churn_risk>=70),'high_vip_potential',(select count(*) from public.restaurant_ai_customer_scores where restaurant_id=rid and vip_potential>=75),'high_referral_potential',(select count(*) from public.restaurant_ai_customer_scores where restaurant_id=rid and referral_potential>=70)),'insights',coalesce((select jsonb_agg(to_jsonb(i) order by case i.severity when 'critical' then 1 when 'warning' then 2 when 'opportunity' then 3 else 4 end,i.generated_at desc) from(select id,customer_user_id,category,insight_type,severity,title,summary,explanation,confidence,evidence,suggested_action,status,seen_at,generated_at from public.restaurant_ai_insights where restaurant_id=rid and status in('active','seen') order by generated_at desc limit 30)i),'[]'::jsonb),'unseen_insights',(select count(*) from public.restaurant_ai_insights where restaurant_id=rid and status='active' and seen_at is null),'methodology',jsonb_build_object('provider','internal','model','ordered-intelligence-v1','version','5.9.1','explainable',true,'protected_attributes_used',false));end$$;

create or replace function public.get_restaurant_ai_forecasts() returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;return coalesce((select jsonb_agg(to_jsonb(x) order by x.horizon,x.metric) from(select metric,horizon,period_start,period_end,predicted_value,lower_bound,upper_bound,confidence,explanation,evidence,generated_at from public.restaurant_ai_forecasts where restaurant_id=rid and period_end>now())x),'[]'::jsonb);end$$;

create or replace function public.get_restaurant_ai_customer_intelligence(p_limit int default 100,p_min_churn numeric default 0) returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;return coalesce((select jsonb_agg(to_jsonb(x) order by x.churn_risk desc,x.lifetime_value_pence desc) from(select s.customer_user_id,coalesce(nullif(trim(concat(cp.first_name,' ',cp.last_name)),''),'Customer') customer_name,s.lifetime_value_pence,s.predicted_future_value_pence,s.churn_risk,s.engagement_score,s.loyalty_score,s.vip_potential,s.referral_potential,s.campaign_responsiveness,s.return_probability,s.evidence,s.computed_at from public.restaurant_ai_customer_scores s left join public.customer_profiles cp on cp.user_id=s.customer_user_id where s.restaurant_id=rid and s.churn_risk>=coalesce(p_min_churn,0) order by s.churn_risk desc,s.lifetime_value_pence desc limit least(greatest(coalesce(p_limit,100),1),500))x),'[]'::jsonb);end$$;

create or replace function public.get_restaurant_ai_recommendations(p_category text default null,p_limit int default 100) returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;return coalesce((select jsonb_agg(to_jsonb(x) order by case x.severity when 'critical' then 1 when 'warning' then 2 when 'opportunity' then 3 else 4 end,x.confidence desc) from(select id,customer_user_id,category,insight_type,severity,title,summary,explanation,confidence,evidence,suggested_action,status,generated_at from public.restaurant_ai_insights where restaurant_id=rid and status in('active','seen') and(p_category is null or category=p_category) limit least(greatest(coalesce(p_limit,100),1),250))x),'[]'::jsonb);end$$;

create or replace function public.get_restaurant_ai_reports(p_limit int default 24) returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;return coalesce((select jsonb_agg(to_jsonb(x) order by x.generated_at desc) from(select id,report_type,period_start,period_end,restaurant_health_score,growth_score,customer_health_score,marketing_score,operations_score,summary,sections,generated_at from public.restaurant_ai_reports where restaurant_id=rid order by generated_at desc limit least(greatest(coalesce(p_limit,24),1),100))x),'[]'::jsonb);end$$;

create or replace function public.get_restaurant_ai_menu_intelligence(p_days int default 90) returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();d int:=least(greatest(coalesce(p_days,90),7),365);result jsonb;begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;with stats as(select oi.menu_item_id,max(oi.item_name) item_name,max(mi.category_id) category_id,sum(oi.quantity)::numeric units,sum(oi.line_total_pence)::numeric revenue_pence,count(distinct oi.order_id)::numeric orders from public.order_items oi join public.orders o on o.id=oi.order_id left join public.menu_items mi on mi.id=oi.menu_item_id where o.restaurant_id=rid and o.payment_status='paid' and o.order_status<>'rejected' and o.created_at>=now()-(d||' days')::interval and oi.menu_item_id is not null group by oi.menu_item_id),pairs as(select a.menu_item_id a_id,b.menu_item_id b_id,max(a.item_name) a_name,max(b.item_name)b_name,count(distinct a.order_id)n from public.order_items a join public.order_items b on b.order_id=a.order_id and a.menu_item_id<b.menu_item_id join public.orders o on o.id=a.order_id where o.restaurant_id=rid and o.payment_status='paid' and o.order_status<>'rejected' and o.created_at>=now()-(d||' days')::interval group by a.menu_item_id,b.menu_item_id order by n desc limit 10),cats as(select c.id,c.name,coalesce(sum(s.revenue_pence),0)revenue_pence,coalesce(sum(s.units),0)units from public.menu_categories c left join stats s on s.category_id=c.id where c.restaurant_id=rid group by c.id,c.name order by revenue_pence desc),peaks as(select extract(dow from created_at)::int day_of_week,extract(hour from created_at)::int hour_of_day,count(*)orders,coalesce(sum(total_pence),0)revenue_pence from public.orders where restaurant_id=rid and payment_status='paid' and order_status<>'rejected' and created_at>=now()-(d||' days')::interval group by 1,2 order by orders desc limit 10) select jsonb_build_object('period_days',d,'best_selling',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from stats order by units desc limit 10)x),'[]'),'worst_selling',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from stats order by units,revenue_pence limit 10)x),'[]'),'most_profitable_proxy',coalesce((select jsonb_agg(to_jsonb(x)) from(select * from stats order by revenue_pence desc limit 10)x),'[]'),'profitability_note','Item cost data is not currently stored, so revenue contribution is used as a transparent profitability proxy rather than gross profit.','frequently_purchased_together',coalesce((select jsonb_agg(to_jsonb(p)) from pairs p),'[]'),'peak_ordering_times',coalesce((select jsonb_agg(to_jsonb(p)) from peaks p),'[]'),'category_performance',coalesce((select jsonb_agg(to_jsonb(c)) from cats c),'[]'),'bundle_opportunities',coalesce((select jsonb_agg(jsonb_build_object('title','Bundle '||a_name||' + '||b_name,'menu_item_ids',jsonb_build_array(a_id,b_id),'pair_orders',n)) from pairs),'[]')) into result;return result;end$$;

create or replace function public.mark_restaurant_ai_insight_seen(p_insight_id uuid,p_dismiss boolean default false) returns boolean language plpgsql security definer set search_path='' as $$declare rid uuid:=public.marketing_member_restaurant_id();n int;begin if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;update public.restaurant_ai_insights set status=case when p_dismiss then 'dismissed' else 'seen' end,seen_at=coalesce(seen_at,now()),dismissed_at=case when p_dismiss then now() else dismissed_at end where id=p_insight_id and restaurant_id=rid;get diagnostics n=row_count;return n=1;end$$;

create or replace function public.get_platform_ai_dashboard(p_days int default 90) returns jsonb language plpgsql stable security definer set search_path='' as $$declare d int:=least(greatest(coalesce(p_days,90),7),365);begin if not private.has_platform_admin_permission('overview:view') then raise exception 'Platform overview permission required' using errcode='42501';end if;return jsonb_build_object('summary',jsonb_build_object('restaurants_with_ai',(select count(distinct restaurant_id) from public.restaurant_ai_runs where status='completed'),'customers_scored',(select count(*) from public.restaurant_ai_customer_scores),'high_churn_customers',(select count(*) from public.restaurant_ai_customer_scores where churn_risk>=70),'active_growth_opportunities',(select count(*) from public.restaurant_ai_insights where status in('active','seen') and severity='opportunity'),'active_risk_alerts',(select count(*) from public.restaurant_ai_insights where status in('active','seen') and severity in('warning','critical')),'average_health_score',(select round(coalesce(avg(restaurant_health_score),0),1) from(select distinct on(restaurant_id) restaurant_id,restaurant_health_score from public.restaurant_ai_reports order by restaurant_id,generated_at desc)x)),'platform_forecasts',jsonb_build_object('weekly_revenue_pence',(select round(coalesce(sum(predicted_value),0)) from public.restaurant_ai_forecasts where metric='revenue_pence' and horizon='weekly' and period_end>now()),'monthly_revenue_pence',(select round(coalesce(sum(predicted_value),0)) from public.restaurant_ai_forecasts where metric='revenue_pence' and horizon='monthly' and period_end>now()),'weekly_delivery_orders',(select round(coalesce(sum(predicted_value),0)) from public.restaurant_ai_forecasts where metric='delivery_orders_count' and horizon='weekly' and period_end>now()),'weekly_collection_orders',(select round(coalesce(sum(predicted_value),0)) from public.restaurant_ai_forecasts where metric='collection_orders_count' and horizon='weekly' and period_end>now())),'benchmarking',coalesce((select jsonb_agg(to_jsonb(x) order by x.restaurant_health_score desc) from(select r.id restaurant_id,r.name,rep.restaurant_health_score,rep.growth_score,rep.customer_health_score,rep.marketing_score,rep.operations_score,(select predicted_value from public.restaurant_ai_forecasts f where f.restaurant_id=r.id and f.metric='revenue_pence' and f.horizon='weekly' order by generated_at desc limit 1)weekly_revenue_forecast_pence,(select count(*) from public.restaurant_ai_customer_scores s where s.restaurant_id=r.id and s.churn_risk>=70)high_churn_customers from public.restaurants r join lateral(select * from public.restaurant_ai_reports ar where ar.restaurant_id=r.id order by generated_at desc limit 1)rep on true limit 200)x),'[]'),'marketing',public.get_platform_marketing_analytics(d),'adoption',jsonb_build_object('marketing_restaurants',(select count(distinct restaurant_id) from public.restaurant_marketing_campaigns),'loyalty_restaurants',(select count(distinct restaurant_id) from public.customer_loyalty_accounts),'vip_restaurants',(select count(distinct restaurant_id) from public.customer_vip_memberships),'challenge_restaurants',(select count(distinct restaurant_id) from public.restaurant_challenges)),'fraud_intelligence',jsonb_build_object('restaurants_with_fraud_insights',(select count(distinct restaurant_id) from public.restaurant_ai_insights where category='fraud' and status in('active','seen'))),'generated_at',now(),'period_days',d,'methodology',jsonb_build_object('version','5.9.1','provider','internal','explainable',true));end$$;

revoke all on function public.refresh_restaurant_ai_intelligence() from public,anon;
revoke all on function public.run_ai_intelligence_cycle(text,int) from public,anon,authenticated;
revoke all on function public.get_restaurant_ai_dashboard() from public,anon;
revoke all on function public.get_restaurant_ai_forecasts() from public,anon;
revoke all on function public.get_restaurant_ai_customer_intelligence(int,numeric) from public,anon;
revoke all on function public.get_restaurant_ai_recommendations(text,int) from public,anon;
revoke all on function public.get_restaurant_ai_reports(int) from public,anon;
revoke all on function public.get_restaurant_ai_menu_intelligence(int) from public,anon;
revoke all on function public.mark_restaurant_ai_insight_seen(uuid,boolean) from public,anon;
revoke all on function public.get_platform_ai_dashboard(int) from public,anon;

grant execute on function public.refresh_restaurant_ai_intelligence() to authenticated;
grant execute on function public.get_restaurant_ai_dashboard() to authenticated;
grant execute on function public.get_restaurant_ai_forecasts() to authenticated;
grant execute on function public.get_restaurant_ai_customer_intelligence(int,numeric) to authenticated;
grant execute on function public.get_restaurant_ai_recommendations(text,int) to authenticated;
grant execute on function public.get_restaurant_ai_reports(int) to authenticated;
grant execute on function public.get_restaurant_ai_menu_intelligence(int) to authenticated;
grant execute on function public.mark_restaurant_ai_insight_seen(uuid,boolean) to authenticated;
grant execute on function public.get_platform_ai_dashboard(int) to authenticated;
grant execute on function public.run_ai_intelligence_cycle(text,int) to service_role;
